    /// <summary>
    /// Finds the METInventLocation record by InventLocationId
    /// </summary>
    /// <param name = "_inventLocationId">InventLocationId</param>
    /// <returns>METInventLocation buffer</returns>
    public static METInventLocation findByInventLocationId(InventLocationId     _inventLocationId)
    {
        METInventLocation       metInventLocation;
        InventLocation          inventLocation;

        select firstonly metInventLocation
            exists join inventLocation
            where inventLocation.RecId == metInventLocation.InventLocation 
            && inventLocation.inventlocationid == _inventLocationId;

        return metInventLocation;
    }

    /// <summary>
    /// Return warehouse unit
    /// </summary>
    /// <param name = "_itemId">ItemId</param>
    /// <param name = "_inventDim">InventDIm</param>
    /// <returns>warehouse unit</returns>
    public static UnitOfMeasureSymbol  getWarehouseUnit(ItemId _itemId, InventDim   _inventDim)
    {
        InventLocation              inventLocation;
        METInventLocation           metInventLocation;
        METExtWMSUnit               externalWarehouseUnit;
        UnitOfMeasureSymbol         warehouseUnit;

        InventItemPurchSetup        inventItemPurchSetup;
        InventItemSalesSetup        inventItemSalesSetup;
        InventTableModule           inventTableModule;
        InventDim                   inventDim;

        select firstonly ExternalWMSUnit from metInventLocation
            join RecId from inventLocation
                where metInventLocation.InventLocation == inventLocation.RecId
                    && inventLocation.InventLocationId == _inventDim.InventLocationId;

        externalWarehouseUnit = metInventLocation.ExternalWMSUnit;

        switch(externalWarehouseUnit)
        {
            case METExtWMSUnit::DefaultInventoryUnit :
                select firstonly UnitId from inventTableModule
                    where inventTableModule.ItemId      == _itemId
                        && inventTableModule.ModuleType == ModuleInventPurchSales::Invent;

                if(inventTableModule.UnitId)
                {
                    warehouseUnit = inventTableModule.UnitId;
                }
                break;

            case METExtWMSUnit::DefaultPurchaseUnit :

                inventDim.clear();
                inventDim.InventSiteId = _inventDim.InventSiteId;
                inventDim = InventDim::findDim(inventDim);

                inventItemPurchSetup = InventItemPurchSetup::find(_itemId, inventDim.inventDimId);

                warehouseUnit       = inventItemPurchSetup.METPurchUnit;
                if(!warehouseUnit)
                {
                    select firstonly UnitId from inventTableModule
                        where inventTableModule.ItemId      == _itemId
                        && inventTableModule.ModuleType == ModuleInventPurchSales::Purch;

                    warehouseUnit   = inventTableModule.UnitId;
                }
                /*if(inventItemPurchSetup.METPurchUnit)
                {
                    warehouseUnit = inventItemPurchSetup.METPurchUnit;
                }*/
                break;

            case METExtWMSUnit::DefaultSellUnit :

                inventDim.clear();
                inventDim.InventSiteId = _inventDim.InventSiteId;
                inventDim = InventDim::findDim(inventDim);

                inventItemSalesSetup = InventItemSalesSetup::find(_itemId, inventDim.inventDimId);
                
                warehouseUnit       = inventItemSalesSetup.METSalesUnit;
                if(!warehouseUnit)
                {
                    select firstonly UnitId from inventTableModule
                        where inventTableModule.ItemId      == _itemId
                        && inventTableModule.ModuleType == ModuleInventPurchSales::Sales;

                    warehouseUnit   = inventTableModule.UnitId;
                }
                /*if(inventItemSalesSetup.METSalesUnit)
                {
                    warehouseUnit = inventItemSalesSetup.METSalesUnit;
                }*/
                break;
        }

        return warehouseUnit;

    }

    /// <summary>
    /// Lookup method for DefaultTMSPalletid.
    /// </summary>
    public void lookupTMSEngine_DefaultTMSPalletid(FormStringControl _control)
    {
        Query                   query = new Query();
        QueryBuildDataSource    qbds;
        SysTableLookup          sysTableLookup;

        sysTableLookup  = sysTableLookup::newParameters(tableNum(MetContainerTypeTable), _control);
        sysTableLookup.addLookupField(fieldnum(MetContainerTypeTable, ContainerTypeCode));
        sysTableLookup.addLookupField(fieldnum(MetContainerTypeTable, InventLocationId));

        InventLocation inventLocation = InventLocation::findRecId(this.InventLocation);
        qbds = query.addDataSource(tableNum(MetContainerTypeTable));
        qbds.addRange(fieldNum(MetContainerTypeTable, InventLocationId)).value(inventLocation.InventLocationId);

        sysTableLookup.parmQuery(query);
        sysTableLookup.performFormLookup();
    }
